  "candidate_id": "route_1"
}"},"provided_route_plan":{"candidate_id":"route_1","rule_ids":["n87","n84","n86"]},"operation":{"stage":"final","index":4,"requested_rule_id":null},"history":[{"source_slot_id":"t083_facts","content":"{"nodes":[{"atom":"G41","id":"G41","parents":[],"rule":null},{"atom":"G49","id":"G49","parents":[],"rule":null},{"atom":"G84","id":"G84","parents":[],"rule":null}]}"},{"source_slot_id":"x04s1_deep_rule_00","content":"{"node":{"atom":"G16","id":"v087_node_0004","parents":["G41","G49","G84"],"rule":"n87"}}"},{"source_slot_id":"x04s1_deep_rule_01","content":"{
